def uniform_lines(grid):
    """(row_indices, col_indices) of lines that are one color throughout."""
    h, w = len(grid), len(grid[0])
    rows = {i for i in range(h) if len(set(grid[i])) == 1}
    cols = {j for j in range(w) if len({r[j] for r in grid}) == 1}
    return rows, cols

def background(grid):
    """The most frequent color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def frontiers(grid):
    """(row_indices, col_indices) of one-color lines whose color is not the background."""
    rows, cols = uniform_lines(grid)
    bg = background(grid)
    return {i for i in rows if grid[i][0] != bg}, {j for j in cols if grid[0][j] != bg}

def segments(idx):
    """Sorted indices split into contiguous runs."""
    idx = sorted(idx)
    out, cur = [], [idx[0]]
    for a in idx[1:]:
        if a == cur[-1] + 1:
            cur.append(a)
        else:
            out.append(cur); cur = [a]
    out.append(cur)
    return out

def blocks(grid):
    """(row_segments, col_segments) of the regions between frontier lines."""
    fr, fc = frontiers(grid)
    rs = segments([i for i in range(len(grid)) if i not in fr])
    cs = segments([j for j in range(len(grid[0])) if j not in fc])
    return rs, cs

def richest_block(grid):
    """The region between frontiers with the most distinct colors."""
    rs, cs = blocks(grid)
    bl = [[[grid[a][b] for b in cj] for a in ci] for ci in rs for cj in cs]
    return max(bl, key=lambda b: len({v for row in b for v in row}))

def tile_blocks(grid, src):
